// Normaliza o payload da Netlify Forms em 1 linha de CRM.
// A Netlify manda { headers, params, query, body } e o formulario vem dentro de body.
const entrada = $input.first().json;
const bruto = entrada.body || entrada;
const d = (bruto.data && typeof bruto.data === 'object') ? bruto.data : bruto;

const texto = (v) => {
  if (v === undefined || v === null) return '';
  if (Array.isArray(v)) return v.map(String).join(' | ');
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v).trim();
};

// Fotos chegam como URL do CDN da Netlify. Guardamos os links, nao o arquivo.
const fotos = ['foto1', 'foto2', 'foto3']
  .map((k) => texto(d[k]))
  .filter((u) => u.indexOf('http') === 0);

const tipo = texto(d.tipo) || texto(d.tipo_panela);
const uberBruto = texto(d.uber).toLowerCase();
const querUber = ['on', 'sim', 'true', '1', 'yes'].indexOf(uberBruto) !== -1;
const tipoMin = tipo.toLowerCase();
const ehB2B = ['industrial', 'restaurante', 'bar', 'padaria', 'rede', 'cozinha']
  .some((p) => tipoMin.indexOf(p) !== -1);

const agora = new Date();
const dia = agora.toISOString().slice(0, 10).replace(/-/g, '');
const idLead = 'WEB-' + dia + '-' + String(Math.floor(Math.random() * 900) + 100);
const prioridade = (querUber || ehB2B) ? 'urgente' : 'normal';
const formName = texto(bruto.form_name) || texto(entrada.form_name);

return [{
  json: {
    id_lead: idLead,
    data_hora: agora.toISOString(),
    nome: texto(d.nome),
    whatsapp: texto(d.whatsapp) || texto(d.telefone),
    cidade_bairro: texto(d.bairro) || texto(d.cidade),
    tipo_panela: tipo,
    problema: texto(d.problema),
    fotos: fotos.join('; '),
    qtd_fotos: fotos.length,
    uber: querUber ? 'sim' : 'nao',
    origem: formName === 'empresa' ? 'site-b2b' : 'site',
    prioridade: prioridade,
    status: 'novo'
  }
}];

