// Fica só com serviços entregues há 1 dia que ainda não pediram avaliação.
const DIAS = 1;
const alvo = new Date();
alvo.setDate(alvo.getDate() - DIAS);
const alvoISO = alvo.toISOString().slice(0, 10);

const paraISO = (v) => {
  if (!v) return '';
  const s = String(v).trim();
  if (s.length >= 10 && s.charAt(4) === '-' && s.charAt(7) === '-') return s.slice(0, 10);
  const partes = s.split('/');
  if (partes.length === 3) {
    const ano = partes[2].length === 2 ? '20' + partes[2] : partes[2];
    return ano + '-' + partes[1].padStart(2, '0') + '-' + partes[0].padStart(2, '0');
  }
  const t = new Date(s);
  return isNaN(t.getTime()) ? '' : t.toISOString().slice(0, 10);
};

const norm = (v) => String(v === undefined || v === null ? '' : v).trim().toLowerCase();
const sair = [];

for (const item of $input.all()) {
  const r = item.json;
  if (norm(r.status) !== 'entregue') continue;
  if (['sim', 's', 'true', '1'].indexOf(norm(r.avaliacao_pedida)) !== -1) continue;
  if (paraISO(r.data_entrega) !== alvoISO) continue;

  const nome = String(r.nome || '').trim();
  if (!nome) continue;

  const dig = String(r.whatsapp || '').replace(/[^0-9]/g, '');
  let numero = '';
  if (dig.length === 10 || dig.length === 11) numero = '55' + dig;
  else if (dig.length >= 12 && dig.slice(0, 2) === '55') numero = dig;
  const link = numero ? 'https://wa.me/' + numero : '';

  const mensagem = 'Oi, ' + nome + '! Obrigado pela confiança! Se você puder avaliar a gente no Google, me ajuda muito. Avaliação honesta vale mais que qualquer anúncio: https://share.google/4yfzvqiftgoAKwqah';

  sair.push({
    json: {
      id_lead: String(r.id_lead || ''),
      nome: nome,
      whatsapp: String(r.whatsapp || ''),
      link_whatsapp: link,
      tipo_panela: String(r.tipo_panela || ''),
      servico: String(r.servico || ''),
      data_entrega: paraISO(r.data_entrega),
      mensagem_avaliacao: mensagem
    }
  });
}

return sair;

